package io.mavsdk.kotlin.plugins.modes

import kotlin.coroutines.resume
import kotlinx.coroutines.channels.awaitClose
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.callbackFlow
import kotlinx.coroutines.suspendCancellableCoroutine

/**
 * Discover and set flight modes at runtime.
 *
 * The modes are queried from the vehicle using the MAVLink standard modes protocol
 * (AVAILABLE_MODES, CURRENT_MODE). For autopilots that don't implement it, a list of known modes is
 * used as a fallback.
 *
 * Modes are identified by name. Standard modes have a fixed name, e.g. "Position" or "Mission",
 * other modes use the name reported by the vehicle. Setting a mode works the same way for both.
 */
class Modes internal constructor(private val native: ModesNative) {
    private var closed = false

    /** Possible results returned for mode requests. */
    enum class Result(val value: Int) {
        /** Unknown result */
        UNKNOWN(0),
        /** Request was successful */
        SUCCESS(1),
        /** No system is connected */
        NO_SYSTEM(2),
        /** Connection error */
        CONNECTION_ERROR(3),
        /** Vehicle is busy */
        BUSY(4),
        /** Request was denied, e.g. because the mode can't be entered right now */
        DENIED(5),
        /** Mode or command is not supported */
        UNSUPPORTED(6),
        /** Request timed out */
        TIMEOUT(7),
        /** Request failed */
        FAILED(8),
        /** No available mode with this name */
        MODE_NOT_FOUND(9),
        /** The available modes have not been received yet */
        MODES_NOT_KNOWN_YET(10);

        companion object {
            fun fromValue(value: Int): Result = entries.find { it.value == value } ?: UNKNOWN
        }
    }

    /**
     * Mode type.
     *
     * @property name Name of the mode, e.g. "Position" or "Stabilize"
     * @property isStandard True if this is a MAVLink standard mode, e.g. "Position", "Safe
     *   Recovery" or "Mission"
     * @property customMode Autopilot specific custom mode
     * @property isUserSelectable True if the mode can be set by the user
     * @property isAdvanced True if the mode is for advanced users only
     * @property isAutoMode True if the mode runs autonomously, e.g. Mission or Land
     */
    data class Mode(
        val name: String,
        val isStandard: Boolean,
        val customMode: Int,
        val isUserSelectable: Boolean,
        val isAdvanced: Boolean,
        val isAutoMode: Boolean,
    )

    /**
     * Subscribe to the list of available modes.
     *
     * The list is updated whenever the vehicle reports that its modes have changed.
     *
     * @return The available modes
     */
    fun availableModes(): List<Mode> = native.availableModes()

    /**
     * Subscribe to the list of available modes.
     *
     * The list is updated whenever the vehicle reports that its modes have changed.
     *
     * @return The available modes
     */
    fun subscribeAvailableModes(): Flow<List<Mode>> = callbackFlow {
        val subscriptionHandle = native.subscribeAvailableModes() { value -> trySend(value) }
        awaitClose { native.unsubscribeAvailableModes(subscriptionHandle) }
    }

    /**
     * Subscribe to the current mode.
     *
     * @return The current mode
     */
    fun currentMode(): Mode = native.currentMode()

    /**
     * Subscribe to the current mode.
     *
     * @return The current mode
     */
    fun subscribeCurrentMode(): Flow<Mode> = callbackFlow {
        val subscriptionHandle = native.subscribeCurrentMode() { value -> trySend(value) }
        awaitClose { native.unsubscribeCurrentMode(subscriptionHandle) }
    }

    /**
     * Set mode by name.
     *
     * The name needs to match exactly (case-sensitive) the name of one of the available modes.
     *
     * @param name Name of the mode to set
     * @return The result of the request.
     */
    suspend fun setMode(name: String): Result = suspendCancellableCoroutine { continuation ->
        val callbackGuard = ModesCallbackGuard()
        native.setModeAsync(name) { result ->
            val parsedResult = Result.fromValue(result)
            if (continuation.isActive && true && callbackGuard.tryClaim()) {
                continuation.resume(parsedResult)
            }
        }
    }

    internal fun destroy() {
        if (closed) return
        closed = true
        native.destroy()
    }

    class ModesException(val result: Result, message: String) : Exception(message)
}

internal interface ModesNative {
    fun availableModes(): List<Modes.Mode>

    fun subscribeAvailableModes(callback: (List<Modes.Mode>) -> Unit): Long

    fun unsubscribeAvailableModes(subscriptionHandle: Long)

    fun currentMode(): Modes.Mode

    fun subscribeCurrentMode(callback: (Modes.Mode) -> Unit): Long

    fun unsubscribeCurrentMode(subscriptionHandle: Long)

    fun setModeAsync(name: String, callback: (Int) -> Unit)

    fun destroy()
}

internal expect fun createModesNative(systemHandle: Long): ModesNative

internal expect class ModesCallbackGuard() {
    fun tryClaim(): Boolean
}
